        [field]: { mode: GridCellModes.View, ignoreModifications: true },
      },
    });
  };

  const handlePointerDown = (event: React.PointerEvent) => {
    // Keep the focus in the cell
    event.preventDefault();
  };

  return (
    <Toolbar>
